const sosDialog=document.getElementById('sosDialog'),sosButton=document.getElementById('sosButton');let currentCoordinates=null;sosButton.addEventListener('click',()=>sosDialog.showModal());document.querySelector('.sos-close').addEventListener('click',()=>sosDialog.close());document.getElementById('getLocation').addEventListener('click',()=>{const label=document.getElementById('locationLabel'),detail=document.getElementById('locationDetail');if(!navigator.geolocation){label.textContent='Location unavailable';detail.textContent='This device does not provide browser location.';return}label.textContent='Finding your location…';detail.textContent='Keep this screen open.';navigator.geolocation.getCurrentPosition(position=>{const {latitude,longitude,accuracy}=position.coords;currentCoordinates={latitude,longitude};label.textContent=`${latitude.toFixed(5)}, ${longitude.toFixed(5)}`;detail.textContent=`Accuracy approximately ${Math.round(accuracy)} metres.`},()=>{label.textContent='Location permission denied';detail.textContent='Enable location access in your phone settings and try again.'},{enableHighAccuracy:true,timeout:12000})});document.getElementById('shareSos').addEventListener('click',async()=>{const location=currentCoordinates?` My location: https://maps.google.com/?q=${currentCoordinates.latitude},${currentCoordinates.longitude}`:' My current location is not attached.';const text=`SOS — I may need assistance.${location}`;if(navigator.share){try{await navigator.share({title:'Safari SOS',text})}catch(e){}}else{await navigator.clipboard?.writeText(text);document.getElementById('toast').textContent='SOS message copied. Send it to your emergency contact.';showToast()}});['contactGuide','localHelp'].forEach(id=>document.getElementById(id).addEventListener('click',()=>{document.getElementById('toast').textContent=id==='contactGuide'?'Add your guide or lodge contact before the trip.':'Emergency numbers will be configured by destination.';showToast()}));
